:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --grid: #0f3460;
  --snake: #4ecca3;
  --food: #e94560;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  max-width: 480px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.125rem;
  font-weight: 600;
  background: var(--grid);
  padding: 6px 14px;
  border-radius: 8px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  border-radius: 12px;
  overflow: hidden;
  background: var(--grid);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 20px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.overlay h2 {
  font-size: 1.375rem;
  color: var(--accent);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 20px;
  border: 2px solid var(--accent);
  border-radius: 10px;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.1s ease;
  flex: 1;
}

.btn:hover {
  background: var(--accent);
  color: var(--card);
}

.btn:focus-visible {
  outline: 3px solid var(--snake);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
  color: var(--card);
}

.btn.primary:hover {
  background: var(--snake);
  border-color: var(--snake);
}

.hint {
  font-size: 0.875rem;
  color: #8a8a9a;
  text-align: center;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
    gap: 12px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 14px;
    font-size: 0.9375rem;
  }
  .hint {
    font-size: 0.8125rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayBtn = document.getElementById('overlayBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 140;

  const COLORS = {
    grid: '#0f3460',
    snake: '#4ecca3',
    snakeHead: '#6ee7b7',
    food: '#e94560'
  };

  let snake, dir, nextDir, food, score, running, paused, gameOver, timer;

  function reset() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    gameOver = false;
    paused = true;
    running = false;
    placeFood();
    draw();
    showOverlay('How to Play', 'Use arrow keys to move.<br>Press <strong>Pause</strong> to start.', 'Start');
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = COLORS.grid;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.snakeHead : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function tick() {
    if (paused || gameOver) return;

    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function startLoop() {
    clearInterval(timer);
    timer = setInterval(tick, TICK_MS);
  }

  function endGame() {
    gameOver = true;
    paused = true;
    running = false;
    clearInterval(timer);
    draw();
    showOverlay('Game Over', 'Final score: <strong>' + score + '</strong><br>Press Restart to play again.', 'Restart');
    pauseBtn.textContent = 'Pause';
  }

  function showOverlay(title, html, btnLabel) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = html;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
    overlayBtn.focus();
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function togglePause() {
    if (gameOver) return;
    if (!running) {
      running = true;
      paused = false;
      hideOverlay();
      pauseBtn.textContent = 'Pause';
      startLoop();
      return;
    }
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    if (paused) {
      showOverlay('Paused', 'Press Resume or P to continue.', 'Resume');
    } else {
      hideOverlay();
      overlayBtn.blur();
    }
  }

  function restart() {
    clearInterval(timer);
    reset();
    pauseBtn.textContent = 'Pause';
  }

  function changeDir(nx, ny) {
    if (nx === -dir.x && ny === -dir.y) return;
    nextDir = { x: nx, y: ny };
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(key)) {
      e.preventDefault();
    }
    if (gameOver && key !== 'r' && key !== 'R') return;

    switch (key) {
      case 'ArrowUp': changeDir(0, -1); break;
      case 'ArrowDown': changeDir(0, 1); break;
      case 'ArrowLeft': changeDir(-1, 0); break;
      case 'ArrowRight': changeDir(1, 0); break;
      case 'p': case 'P': togglePause(); break;
      case 'r': case 'R': restart(); break;
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  overlayBtn.addEventListener('click', () => {
    if (gameOver) {
      restart();
    } else {
      togglePause();
    }
  });

  reset();
})();
